	"math/rand"
	"time"

	"github.com/hajimehoshi/ebiten/v2"
	"github.com/hajimehoshi/ebiten/v2/ebitenutil"
)

const (
	ScreenWidth    = 800
	ScreenHeight   = 600
	ThrustForce    = 0.1
	BulletSpeed    = 4.0
	BulletLifespan = 1.0 // Seconds

	// Score awarded between free ships
	ExtraLifeInterval = 10000

	// UFO constants
	UFOSpawnInterval = 10 * time.Second
	BigUFORadius     = 20.0
	SmallUFORadius   = 15.0
	BigUFOSpeed      = 0.5
	SmallUFOSpeed    = 1.0
	BigUFOScore      = 200
	SmallUFOScore    = 1000
)

func NewGame() *Game {
	g := &Game{
		ScreenWidth:        ScreenWidth,
		ScreenHeight:       ScreenHeight,
		Lives:              3 + rand.Intn(3), // 3-5 lives
		Level:              1,
		UFOs:               []*UFO{},
		UFOBullets:         []*UFOBullet{},
		LastUFOSpawn:       time.Now(),
		NextExtraLifeScore: ExtraLifeInterval,
		Particles:          []*Particle{},
		Sound:              NewSoundManager(),
		GameState:          2,
	}

	return g
}

func (g *Game) resetPlayfield() {
	g.Ship = nil
	g.Asteroids = []*Asteroid{}
	g.Bullets = []*Bullet{}
	g.UFOs = []*UFO{}
	g.UFOBullets = []*UFOBullet{}
	g.Score = 0
	g.Lives = 3 + rand.Intn(3) // 3-5 lives
	g.Level = 1
	g.LastShot = time.Time{}
	g.LastUFOSpawn = time.Now()
	g.NextExtraLifeScore = ExtraLifeInterval
	g.Particles = []*Particle{}
	g.RespawnTimer = 0
	g.GameState = 0

	g.Ship = &Ship{
		Position: Vector2D{X: float64(ScreenWidth) / 2, Y: float64(ScreenHeight) / 2},
		Rotation: -math.Pi / 2,
	}

	g.spawnAsteroids(4, 3) // 4 Large asteroids
}

func (g *Game) spawnAsteroids(count int, size int) {
	for i := 0; i < count; i++ {
		var pos Vector2D
		if rand.Intn(2) == 0 {
			pos.X = rand.Float64() * float64(g.ScreenWidth)
			if rand.Intn(2) == 0 {
				pos.Y = 0
			} else {
				pos.Y = float64(g.ScreenHeight)
			}
		} else {
			pos.Y = rand.Float64() * float64(g.ScreenHeight)
			if rand.Intn(2) == 0 {
				pos.X = 0
			} else {
				pos.X = float64(g.ScreenWidth)
			}
		}

		speed := rand.Float64() + 0.5
		angle := rand.Float64() * 2 * math.Pi
		vel := Vector2D{X: math.Cos(angle) * speed, Y: math.Sin(angle) * speed}

		radius := float64(size * 15)
		points := 8 + rand.Intn(4)
		shape := make([]Vector2D, points)
		for j := 0; j < points; j++ {
			angle := (float64(j) / float64(points)) * 2 * math.Pi
			r := radius * (0.8 + rand.Float64()*0.4)
			shape[j] = Vector2D{
				X: math.Cos(angle) * r,
				Y: math.Sin(angle) * r,
			}
		}

		g.Asteroids = append(g.Asteroids, &Asteroid{
			Position:      pos,
			Velocity:      vel,
			Rotation:      rand.Float64() * 2 * math.Pi,
			RotationSpeed: (rand.Float64() - 0.5) * 0.05,
			Shape:         shape,
			Size:          size,
			Radius:        radius,
		})
	}
}

func (g *Game) splitAsteroid(index int) {
	a := g.Asteroids[index]
	// Remove asteroid
	g.Asteroids = append(g.Asteroids[:index], g.Asteroids[index+1:]...)

	if a.Size > 1 {
		newSize := a.Size - 1
		for i := 0; i < 2; i++ {
			// Diverging velocity
			angle := rand.Float64() * 2 * math.Pi // Random direction for split pieces?
			// Or based on old velocity? Spec says "diverging velocities".
			// Let's just randomizing slightly or rotate old velocity.
			// Simple: random direction, slightly faster.
			speed := math.Hypot(a.Velocity.X, a.Velocity.Y) * 1.5
			vel := Vector2D{X: math.Cos(angle) * speed, Y: math.Sin(angle) * speed}

			radius := float64(newSize * 15)
			points := 8 + rand.Intn(4)
			shape := make([]Vector2D, points)
			for j := 0; j < points; j++ {
				ang := (float64(j) / float64(points)) * 2 * math.Pi
				r := radius * (0.8 + rand.Float64()*0.4)
				shape[j] = Vector2D{
					X: math.Cos(ang) * r,
					Y: math.Sin(ang) * r,
				}
			}

			g.Asteroids = append(g.Asteroids, &Asteroid{
				Position:      a.Position,
				Velocity:      vel,
				Rotation:      rand.Float64() * 2 * math.Pi,
				RotationSpeed: (rand.Float64() - 0.5) * 0.05,
				Shape:         shape,
				Size:          newSize,
				Radius:        radius,
			})
		}
	}
}

func (g *Game) spawnExplosion(pos Vector2D) {
	for i := 0; i < 10; i++ {
		angle := rand.Float64() * 2 * math.Pi
		speed := rand.Float64() * 2.0
		vel := Vector2D{X: math.Cos(angle) * speed, Y: math.Sin(angle) * speed}

		g.Particles = append(g.Particles, &Particle{
			Position:      pos,
			Velocity:      vel,
			Rotation:      rand.Float64() * 2 * math.Pi,
			RotationSpeed: (rand.Float64() - 0.5) * 0.2,
			Lifespan:      1.0 + rand.Float64(),
			Length:        5.0 + rand.Float64()*10.0,
		})
	}
}

func (g *Game) killShip() {
	if g.Ship == nil {
		return
	}
	if g.Sound != nil {
		g.Sound.PlayShipExplosion()
	}
	g.spawnExplosion(g.Ship.Position)
	g.Ship = nil
	g.Lives--
	g.RespawnTimer = 2.0
}

// grantExtraLives awards a free ship for every extra-life threshold the score
// has crossed and returns how many were granted, so a single high-value kill
// that jumps several thresholds pays out in full.
func (g *Game) grantExtraLives() int {
	granted := 0
	for g.Score >= g.NextExtraLifeScore {
		g.Lives++
		g.NextExtraLifeScore += ExtraLifeInterval
		granted++
	}
	return granted
}

func (g *Game) wrap(pos Vector2D) Vector2D {
	w, h := float64(g.ScreenWidth), float64(g.ScreenHeight)
	if pos.X < 0 {
		pos.X = w
	} else if pos.X > w {
		pos.X = 0
	}
	if pos.Y < 0 {
		pos.Y = h
	} else if pos.Y > h {
		pos.Y = 0
	}
	return pos
}

func (g *Game) Update() error {
	if g.GameState == 2 {
		if ebiten.IsKeyPressed(ebiten.KeyEnter) {
			g.resetPlayfield()
		}
		return nil
	}

	if g.GameState == 1 {
		// Game Over
		if ebiten.IsKeyPressed(ebiten.KeyEnter) {
			// Restart
			if g.Sound != nil {
				g.Sound.Close()
			}
			*g = *NewGame()
			g.resetPlayfield()
		}
		return nil
	}

	// Update Particles
	for i := len(g.Particles) - 1; i >= 0; i-- {
		p := g.Particles[i]
		p.Position.X += p.Velocity.X
		p.Position.Y += p.Velocity.Y
		p.Rotation += p.RotationSpeed
		p.Lifespan -= 1.0 / 60.0
		if p.Lifespan <= 0 {
			g.Particles = append(g.Particles[:i], g.Particles[i+1:]...)
		}
	}

	// Respawn Timer
	if g.RespawnTimer > 0 {
		g.RespawnTimer -= 1.0 / 60.0
		if g.RespawnTimer <= 0 {
			if g.Lives > 0 {
				// Respawn Ship
				g.Ship = &Ship{
